/** A list of [`LIST_LEN`] items with operations that change one item at a time. */
export class BigList extends UndraStore {
  readonly items: Signal<Item[]> = new Signal<Item[]>([]);
  /** Computed by the core; read-only. */
  readonly count: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.items, this.count];
  }

  /** A list of [`LIST_LEN`] items numbered from 1. */
  static async create(core: UndraCore = UndraCore.shared): Promise<BigList> {
    const handle = await core.construct(
      UndraIds.Objects.BigList.typeId,
      UndraIds.Objects.BigList.new,
      new Uint8Array(0),
    );
    const store = new BigList(core, handle);
    await core.observe(handle, ALL_SIGNALS, true);
    return store;
  }

  /**
   * Inserts a new row with `label` so that it ends at `index` (`index == len` appends), and
   * returns its identity. One keyed `Insert`.
   * @throws {ListError}
   */
  async insertAt(index: number, label: string): Promise<number> {
    const w = new UndraWriter();
    w.writeU32(index);
    w.writeStr(label);
    let body: Uint8Array;
    try {
      body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.insertAt,
        w.finish(),
      );
    } catch (error) {
      throw ListError.fromReply(error);
    }
    return decodeValue(codecs.u32, body);
  }

  /**
   * Moves the row at `from` so that it ends at `to`. One keyed `Move`.
   * @throws {ListError}
   */
  async moveItem(from: number, to: number): Promise<void> {
    const w = new UndraWriter();
    w.writeU32(from);
    w.writeU32(to);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.moveItem,
        w.finish(),
      );
    } catch (error) {
      throw ListError.fromReply(error);
    }
  }

  /**
   * Removes the row at `index`. One keyed `Remove`.
   * @throws {ListError}
   */
  async removeAt(index: number): Promise<void> {
    const w = new UndraWriter();
    w.writeU32(index);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.removeAt,
        w.finish(),
      );
    } catch (error) {
      throw ListError.fromReply(error);
    }
  }

  /**
   * Replaces the list with a fresh one of [`LIST_LEN`] items. The platform receives the keyed
   * patch that turns the old list into the new one (a full value if they have little in
   * common).
   */
  async reset(): Promise<void> {
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.BigList.reset,
      new Uint8Array(0),
    );
  }

  /**
   * Changes the label of the row at `index` and bumps its version. One keyed `Update`.
   * @throws {ListError}
   */
  async updateAt(index: number, label: string): Promise<void> {
    const w = new UndraWriter();
    w.writeU32(index);
    w.writeStr(label);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.updateAt,
        w.finish(),
      );
    } catch (error) {
      throw ListError.fromReply(error);
    }
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    switch (signalId) {
      case 0:
        if (op === ChangeOp.FullValue) {
          this.items._set(decodeValue(vecItem, value));
        } else if (op === ChangeOp.KeyedPatch) {
          const r = new UndraReader(value);
          const ops = decodePatch(r, ItemCodec);
          r.finish();
          try {
            this.items._set(applyPatch(this.items.peek(), ops));
          } catch (error) {
            if (!(error instanceof PatchError)) throw error;
            this._resync(0);
          }
        }
        break;
      case 1:
        if (op === ChangeOp.FullValue) {
          this.count._set(decodeValue(codecs.u32, value));
        }
        break;
      default:
        break;
    }
  }

  /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
  private _resync(signalId: number): void {
    void this.core.observe(this.handle, signalId, false);
    void this.core.observe(this.handle, signalId, true);
  }
}

/** A counter with a change tally and a computed parity. */
export class Counter extends UndraStore {
  readonly count: Signal<number> = new Signal<number>(0);
  readonly changes: Signal<number> = new Signal<number>(0);
  /** Computed by the core; read-only. */
  readonly parity: Signal<Parity> = new Signal<Parity>("even");

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.count, this.changes, this.parity];
  }

  /** A counter at zero with no changes made. */
  static async create(core: UndraCore = UndraCore.shared): Promise<Counter> {
    const handle = await core.construct(
      UndraIds.Objects.Counter.typeId,
      UndraIds.Objects.Counter.new,
      new Uint8Array(0),
    );
    const store = new Counter(core, handle);
    await core.observe(handle, ALL_SIGNALS, true);
    return store;
  }

  /**
   * Adds `amount` (which may be negative) and counts the change: one transaction, so one
   * change-set for `count`, `changes` and `parity` together. The count saturates instead of
   * overflowing.
   */
  async add(amount: number): Promise<void> {
    const w = new UndraWriter();
    w.writeI32(amount);
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Counter.add,
      w.finish(),
    );
  }

  /** Subtracts one. */
  async decrement(): Promise<void> {
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Counter.decrement,
      new Uint8Array(0),
    );
  }

  /** Adds one. */
  async increment(): Promise<void> {
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Counter.increment,
      new Uint8Array(0),
    );
  }

  /** Sets the count back to zero and forgets the changes, in one transaction. */
  async reset(): Promise<void> {
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Counter.reset,
      new Uint8Array(0),
    );
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    switch (signalId) {
      case 0:
        if (op === ChangeOp.FullValue) {
          this.count._set(decodeValue(codecs.i32, value));
        }
        break;
      case 1:
        if (op === ChangeOp.FullValue) {
          this.changes._set(decodeValue(codecs.u32, value));
        }
        break;
      case 2:
        if (op === ChangeOp.FullValue) {
          this.parity._set(decodeValue(ParityCodec, value));
        }
        break;
      default:
        break;
    }
  }
}

/** A store that commits many transactions at once, for the coalesced-delivery scenarios. */
export class Stress extends UndraStore {
  readonly value: Signal<bigint> = new Signal<bigint>(0n);
  readonly progress: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle, { noCoalesce: [1] });
    this._signals = [this.value, this.progress];
  }

  /** A store with both signals at zero. */
  static async create(core: UndraCore = UndraCore.shared): Promise<Stress> {
    const handle = await core.construct(
      UndraIds.Objects.Stress.typeId,
      UndraIds.Objects.Stress.new,
      new Uint8Array(0),
    );
    const store = new Stress(core, handle);
    await core.observe(handle, ALL_SIGNALS, true);
    return store;
  }

  /**
   * Commits `transactions` transactions now, each one write of the signal `mode` names: one
   * change-set per transaction, the way data that arrives in the core on its own does.
   */
  async burst(mode: StressMode, transactions: number): Promise<void> {
    const w = new UndraWriter();
    StressModeCodec.encode(w, mode);
    w.writeU32(transactions);
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Stress.burst,
      w.finish(),
    );
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    switch (signalId) {
      case 0:
        if (op === ChangeOp.FullValue) {
          this.value._set(decodeValue(codecs.u64, value));
        }
        break;
      case 1:
        if (op === ChangeOp.FullValue) {
          this.progress._set(decodeValue(codecs.u32, value));
        }
        break;
      default:
        break;
    }
  }
}

/** The to-do list: what the UI observes (`todos`, `filter`, `visible`, `remaining`) and calls. */
export class Todos extends UndraStore {
  readonly todos: Signal<Todo[]> = new Signal<Todo[]>([]);
  readonly filter: Signal<Filter> = new Signal<Filter>("all");
  /** Computed by the core; read-only. */
  readonly visible: Signal<Todo[]> = new Signal<Todo[]>([]);
  /** Computed by the core; read-only. */
  readonly remaining: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.todos, this.filter, this.visible, this.remaining];
  }

  /** An empty list showing every item. */
  static async create(core: UndraCore = UndraCore.shared): Promise<Todos> {
    const handle = await core.construct(
      UndraIds.Objects.Todos.typeId,
      UndraIds.Objects.Todos.new,
      new Uint8Array(0),
    );
    const store = new Todos(core, handle);
    await core.observe(handle, ALL_SIGNALS, true);
    return store;
  }

  /**
   * Adds an item at the end of the list.
   * @throws {TodoError}
   */
  async add(title: string, signal?: AbortSignal): Promise<Todo> {
    const w = new UndraWriter();
    w.writeStr(title);
    let body: Uint8Array;
    try {
      body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.add,
        w.finish(),
        signal,
      );
    } catch (error) {
      throw TodoError.fromReply(error);
    }
    return decodeValue(TodoCodec, body);
  }

  /** Removes every finished item. */
  async clearDone(): Promise<void> {
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Todos.clearDone,
      new Uint8Array(0),
    );
  }

  /** Removes the item with `id`; unknown ids are ignored. */
  async remove(id: string): Promise<void> {
    const w = new UndraWriter();
    w.writeUuid(id);
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Todos.remove,
      w.finish(),
    );
  }

  /** Chooses which items `visible` holds. */
  async setFilter(filter: Filter): Promise<void> {
    const w = new UndraWriter();
    FilterCodec.encode(w, filter);
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Todos.setFilter,
      w.finish(),
    );
  }

  /** Flips the `done` flag of the item with `id`; unknown ids are ignored. */
  async toggle(id: string): Promise<void> {
    const w = new UndraWriter();
    w.writeUuid(id);
    await this.core.call(
      { target: CallTarget.ObjectMethod, handle: this.handle },
      UndraIds.Objects.Todos.toggle,
      w.finish(),
    );
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    switch (signalId) {
      case 0:
        if (op === ChangeOp.FullValue) {
          this.todos._set(decodeValue(vecTodo, value));
        } else if (op === ChangeOp.KeyedPatch) {
          const r = new UndraReader(value);
          const ops = decodePatch(r, TodoCodec);
          r.finish();
          try {
            this.todos._set(applyPatch(this.todos.peek(), ops));
          } catch (error) {
            if (!(error instanceof PatchError)) throw error;
            this._resync(0);
          }
        }
        break;
      case 1:
        if (op === ChangeOp.FullValue) {
          this.filter._set(decodeValue(FilterCodec, value));
        }
        break;
      case 2:
        if (op === ChangeOp.FullValue) {
          this.visible._set(decodeValue(vecTodo, value));
        }
        break;
      case 3:
        if (op === ChangeOp.FullValue) {
          this.remaining._set(decodeValue(codecs.u32, value));
        }
        break;
      default:
        break;
    }
  }

  /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
  private _resync(signalId: number): void {
    void this.core.observe(this.handle, signalId, false);
    void this.core.observe(this.handle, signalId, true);
  }
}

const vecItem = codecs.vec(ItemCodec);
const vecTodo = codecs.vec(TodoCodec);
